# Contenu des pages conducteur et demande. Les réponses et critères restent à valider avant publication.
F=lambda n,l,t='text',rq=True,x='':f'<div class="fd"><label for="{n}">{l}{"" if rq else " <small>(facultatif)</small>"}</label><input id="{n}" name="{n}" type="{t}" {"required" if rq else ""} {x}><p class="er" id="{n}-e"></p></div>'
CON='<div class="fd ck"><label><input type="checkbox" name="consent" required> <span>J\'accepte que ROAM utilise ces informations pour me recontacter. <a href="../../premium-v2/confidentialite/">Données personnelles</a></span></label><p class="er" id="consent-e"></p></div><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">'
ST='<p class="st" role="status" data-st></p>'
I='../img/'
RK=lambda h,t:f'<a href="{h}"><span class="rl" data-t="{t}">{t}</span></a>'
# En-tête et pied de page propres aux conducteurs
BARD='<header class="bar lite"><a class="logo" href="./" aria-label="roam conducteurs, nom provisoire"><i></i><span>roam</span><em>conducteurs</em></a><nav class="links" aria-label="Navigation conducteurs">'+RK('#etapes','Les étapes')+RK('#estimation','Estimation')+RK('#faq','Questions')+'</nav><div class="acts"><a class="drv" href="../"><span class="rl" data-t="Annonceurs">Annonceurs</span></a><a class="btn sm" href="#candidature"><span class="rl" data-t="Rejoindre la liste">Rejoindre la liste</span></a><button class="menu" data-menu aria-expanded="false" aria-controls="sheet">Menu</button></div></header>\n<div class="sheet" data-sheet id="sheet"><a href="#etapes">Les étapes</a><a href="#estimation">Estimation</a><a href="#faq">Questions</a><a href="#candidature">Rejoindre la liste</a><a href="../">Annonceurs</a></div>\n'
FTD='<div class="ft"><div class="fl">'+RK('#etapes','Les étapes')+RK('#estimation','Estimation')+RK('#faq','Questions')+RK('#candidature','Rejoindre la liste')+'</div><div class="fl">'+RK('../','Annonceurs')+RK('../../premium-v2/confidentialite/','Données personnelles')+'</div></div>'
# Le haut de page : la photo est d'abord une carte, le scroll l'ouvre sur tout l'écran
RD=[('Inscription','Le formulaire, en quelques minutes.'),('Vérification','Votre voiture et votre zone.'),('Sélection','Une campagne vous est proposée.'),('Pose','Par des professionnels.'),('Circulation','Vos trajets, comme d\'habitude.'),('Rémunération','Selon le contrat.')]
FAQ=[('Est-ce que le covering abîme la voiture ?','Un film posé et retiré dans de bonnes conditions protège généralement la peinture. L\'état de votre carrosserie sera vérifié avant la pose.'),
 ('Qui s\'occupe de la pose et du retrait ?','ROAM organise la pose et le retrait avec des professionnels, aux conditions prévues dans le contrat.'),
 ('Que se passe-t-il pour mon assurance ?','Les démarches éventuelles seront précisées avant la signature. Votre situation sera regardée au cas par cas.'),
 ('Quelles sont mes obligations ?','Garder la voiture en bon état, rouler selon les conditions convenues et valider vos kilomètres.'),
 ('Mon trajet est-il suivi en détail ?','Non, le principe est de valider des kilomètres et de grandes zones, pas chacun de vos trajets. La méthode exacte sera précisée dans le contrat.'),
 ('Suis-je sûr d\'avoir une campagne ?','Non. Une campagne dépend de votre zone, de votre voiture et des besoins des annonceurs.')]
FQ=f'''<section class="faq2" id="faq" aria-labelledby="fa-t"><h2 class="big" id="fa-t">Vos questions</h2><div class="fql">{''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in FAQ)}</div></section>'''
D=f'''<section class="dh" aria-labelledby="dh-t"><div class="dht"><p class="eye">Devenir conducteur</p><h1 class="fit" id="dh-t">Vous roulez déjà.</h1><a class="btn" href="#candidature"><span class="rl" data-t="Rejoindre la liste">Rejoindre la liste</span></a><p class="dhp">Une publicité sur votre voiture, une rémunération selon les conditions du programme.</p></div><figure class="dhi"><img src="{I}p_car.webp" alt="Une voiture habillée dans une rue" width="1920" height="1076"></figure><div class="dh2"><h2 class="fit">Votre voiture peut vous rapporter.</h2></div></section>
<section class="rd" id="etapes" aria-labelledby="rd-t"><h2 class="big" id="rd-t">Six étapes, du formulaire à la route</h2><div class="rt"><i class="rdl"></i><i class="rdd"></i><ol>{''.join(f'<li><h3>{t}</h3><p>{d}</p></li>' for t,d in RD)}</ol></div></section>
<section class="sim ovl" id="estimation" aria-labelledby="si-t"><div><p class="eye">Combien peut-on gagner ?</p><h2 class="big" id="si-t">Une estimation, pas une promesse</h2><p class="lead2">Votre revenu dépend de la voiture, de la zone, de la campagne, des kilomètres éligibles et du contrat.</p><form class="sf" onsubmit="return false"><fieldset><legend>Votre zone</legend><div class="op"><label><input type="radio" name="z" value="1"><span>Zone rurale</span></label><label><input type="radio" name="z" value="2" checked><span>Périphérie</span></label><label><input type="radio" name="z" value="3"><span>Grande ville</span></label></div></fieldset><fieldset><legend>Format de campagne</legend><div class="op"><label><input type="radio" name="f" value="1"><span>Classique</span></label><label><input type="radio" name="f" value="2" checked><span>Medium</span></label><label><input type="radio" name="f" value="3"><span>Complet</span></label></div></fieldset><div class="rg"><label for="simkm">Kilomètres par mois <output id="kmo" for="simkm">1 000 km</output></label><input id="simkm" type="range" min="200" max="3000" step="100" value="1000"></div></form></div>
<div class="res" aria-live="polite"><p class="rl2">Niveau indicatif</p><strong id="lvl">Moyen</strong><div class="bar2"><i id="gau"></i></div><p class="amt" id="amt">Montant : à définir avant publication</p><p class="fine">Estimation indicative, jamais garantie. Aucune rémunération sans campagne et contrat signé.</p></div></section>
{FQ}'''
END=f'''<section class="wrapc jnw" id="candidature" aria-labelledby="ca-t"><div class="cta jn"><div class="jnh"><p class="eye">Rejoindre la liste des conducteurs</p><h2 id="ca-t">Votre voiture prend la route avec nous&nbsp;?</h2><p>Une candidature ne garantit pas une campagne immédiate. Nous vous recontactons si une campagne correspond à votre zone et à votre voiture.</p></div>
<form class="fm" data-form="driverEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('email','E-mail','email')}{F('phone','Téléphone','tel')}{F('city','Ville ou région')}{F('car','Marque et modèle du véhicule')}{F('year','Année du véhicule','number',True,'min="1990" max="2027" inputmode="numeric"')}{F('km','Kilométrage approximatif','number',True,'min="0" inputmode="numeric"')}<div class="fd"><label for="info">Informations <small>(facultatif)</small></label><input id="info" name="info" type="text"></div></div>{CON}<button class="btn" type="submit">Envoyer ma candidature</button>{ST}</form></div></section>'''
page('conducteur','Devenir conducteur','Recevez une rémunération pour une publicité sur votre voiture, selon les conditions du programme ROAM.',D,'<script src="../app.js"></script><script src="../conducteur.js"></script>',END,BARD,FTD)
L=f'''<section class="cand dm" aria-labelledby="de-t"><div class="cah"><p class="eye">Créer ma campagne</p><h1 class="big" id="de-t">Parlons de votre campagne</h1><p class="lead2">Dites-nous ce que vous voulez faire connaître et où. Nous revenons vers vous avec une proposition.</p></div>
<form class="fm" data-form="quoteEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('company','Entreprise')}{F('email','E-mail','email')}{F('phone','Téléphone','tel',False)}{F('zones','Villes ou zones visées')}<div class="fd"><label for="format">Format envisagé <small>(facultatif)</small></label><select id="format" name="format"><option value="">Je ne sais pas encore</option><option>Classique</option><option>Medium</option><option>Complet</option></select></div></div><div class="fd"><label for="message">Votre projet <small>(facultatif)</small></label><textarea id="message" name="message" rows="3"></textarea></div>{CON}<button class="btn" type="submit">Envoyer ma demande</button>{ST}</form></section>'''
page('demande','Créer ma campagne','Demandez une proposition pour votre campagne de publicité sur véhicules.',L,'<script>document.documentElement.classList.remove("mo")</script>')
